import numeral from 'numeral';
import { isNil } from 'lodash';
import { Maskers } from '../';
import { ERRORS } from './';

const validIntegerRegex = /^-?[0-9]*([0-9]*)?$/;

function integerValidator({ errors, value }) {
  if (!isNil(value) && value !== '') {
    const maskedValue = Maskers.integer(value);
    const newValue = numeral(maskedValue.trim()).value();

    if (
      isNil(newValue) ||
      isNaN(newValue) ||
      value.toString() !== maskedValue ||
      !validIntegerRegex.test(maskedValue)
    ) {
      errors.push(ERRORS.invalidInteger);
    }
  }

  return errors;
}

export default integerValidator;
